#!/usr/bin/env node
/**
 * Derives the app's CSS from its skin (ADR 0022, 0025): `renderCss(resolveSkin(tokens, skin))`
 * reads the published token source, overlays `skin.json`, and writes `src/skin.generated.css`.
 * The app imports that generated file instead of the default `tokens.generated.css`, so the
 * app's identity is an overlay, never a fork. Replayed on every dev/build.
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

import { renderCss, resolveSkin } from '@nomosui/react'

const require = createRequire(import.meta.url)
const here = path.dirname(fileURLToPath(import.meta.url))
const root = path.resolve(here, '..')

const tokens = JSON.parse(readFileSync(require.resolve('@nomosui/react/tokens/tokens.json'), 'utf8'))
const skin = JSON.parse(readFileSync(path.join(root, 'skin.json'), 'utf8'))

const css = `/* Generated by scripts/skin.build.mjs — do not edit by hand. Replay: npm run skin */
${renderCss(resolveSkin(tokens, skin))}`

writeFileSync(path.join(root, 'src', 'skin.generated.css'), css)
console.log('skin: wrote src/skin.generated.css')
